example.code:
-- Before: the query scans the whole orders table
EXPLAIN ANALYZE
SELECT * FROM orders WHERE customer_id = 42 AND created_at >= '2026-01-01';

CREATE INDEX idx_orders_customer_date ON orders (customer_id, created_at);

-- After: Index Scan using idx_orders_customer_date ... (a few ms instead of seconds)

exercises.answer:
WITH ranked AS (
  SELECT o.*, ROW_NUMBER() OVER (PARTITION BY customer_id ORDER BY ordered_at DESC) AS rn
  FROM orders o
)
SELECT * FROM ranked WHERE rn = 1;
